package de.fitnesscoach.ui.plan;
import android.app.Application;import androidx.annotation.NonNull;import androidx.lifecycle.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import de.fitnesscoach.data.db.FitnessCoachDatabase;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.*;import de.fitnesscoach.domain.plan.TrainingPlanService;
public final class PlanViewModel extends AndroidViewModel{private final FitnessCoachRepository repo;private final TrainingPlanService service;private final ExecutorService ex=Executors.newSingleThreadExecutor();private final MutableLiveData<List<PlannedWorkoutEntity>>state=new MutableLiveData<>();private LocalDate week=LocalDate.now().with(DayOfWeek.MONDAY);public PlanViewModel(@NonNull Application a){super(a);repo=new RoomFitnessCoachRepository(FitnessCoachDatabase.getInstance(a));service=new TrainingPlanService(repo);}public LiveData<List<PlannedWorkoutEntity>>getState(){return state;}public LocalDate getWeek(){return week;}public void load(){LocalDate w=week;ex.execute(()->{service.ensureWeek(w);state.postValue(repo.getPlannedWorkouts(w,w.plusDays(6)));});}public void previous(){week=week.minusWeeks(1);load();}public void next(){week=week.plusWeeks(1);load();}public void adaptToday(){ex.execute(()->{service.adapt(LocalDate.now());load();});}@Override protected void onCleared(){ex.shutdownNow();}}
